window.ScripturaLexicons.BDAG_PART_0034 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aner-bdag\" data-source=\"BDAG\" data-search=\"ἀνήρ aner homem marido pessoa varão adulto masculino homem celestial Jesus juiz mundo Atos Paulo Tiago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνήρ</td><td>Substantivo masculino</td><td>homem; marido; pessoa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anerethen-bdag\" data-source=\"BDAG\" data-search=\"ἀνῃρέθην anerethen veja ἀναιρέω remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνῃρέθην</td><td>Remissão</td><td>veja ἀναιρέω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anephthen-bdag\" data-source=\"BDAG\" data-search=\"ἀνήφθην anephthen veja ἀνάπτω remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνήφθην</td><td>Remissão</td><td>veja ἀνάπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anechthen-bdag\" data-source=\"BDAG\" data-search=\"ἀνήχθην anechthen veja ἀνάγω remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνήχθην</td><td>Remissão</td><td>veja ἀνάγω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthexomai-bdag\" data-source=\"BDAG\" data-search=\"ἀνθέξομαι anthexomai veja ἀντέχω remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθέξομαι</td><td>Remissão</td><td>veja ἀντέχω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antheo-bdag\" data-source=\"BDAG\" data-search=\"ἀνθέω antheo florescer terra flores imperecíveis Apocalipse Pedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθέω</td><td>Verbo</td><td>florescer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-antheros-bdag\" data-source=\"BDAG\" data-search=\"ἀνθηρός antheros esplêndido brilhante cabelo Apocalipse Pedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθηρός</td><td>Adjetivo</td><td>esplêndido; brilhante</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthistemi-bdag\" data-source=\"BDAG\" data-search=\"ἀνθίστημι anthistemi opor resistir fazer oposição firmar posição Mateus Atos Gálatas Tiago Pedro Romanos Efésios Timóteo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθίστημι</td><td>Verbo</td><td>opor-se; resistir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthomologeomai-bdag\" data-source=\"BDAG\" data-search=\"ἀνθομολογέομαι anthomologeomai louvar agradecer Deus Lucas 2.38 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθομολογέομαι</td><td>Verbo</td><td>louvar; agradecer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthos-bdag\" data-source=\"BDAG\" data-search=\"ἄνθος anthos flor florescência flor silvestre esplendor fragrância Tiago 1 Pedro Apocalipse Pedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνθος</td><td>Substantivo neutro</td><td>flor; fragrância</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthrakia-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρακιά anthrakia fogo de carvão brasas João 18.18 21.9 peixe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρακιά</td><td>Substantivo feminino</td><td>fogo de carvão; braseiro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthrax-bdag\" data-source=\"BDAG\" data-search=\"ἄνθραξ anthrax carvão brasas ardentes cabeça vergonha remorso Romanos 12.20 Provérbios 25.22 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνθραξ</td><td>Substantivo masculino</td><td>carvão; brasa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropareskeo-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρωπαρεσκέω anthropareskeo agradar pessoas bajular favorecer pessoas sacrificar princípios Inácio Romanos Gálatas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρωπαρεσκέω</td><td>Verbo</td><td>agradar pessoas; buscar seu favor</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropareskos-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρωπάρεσκος anthropareskos bajulador adulador servil escravo Efésios Colossenses 2 Clemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρωπάρεσκος</td><td>Adjetivo substantivado</td><td>bajulador; adulador servil</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropinos-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρώπινος anthropinos humano pessoa natureza humana humanidade sabedoria tribunal instituição 1 Coríntios Romanos Tiago Atos 1 Pedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρώπινος</td><td>Adjetivo</td><td>humano</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropinos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρωπίνως anthropinos advérbio como ser humano forma humana Deus Inácio Efésios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρωπίνως</td><td>Advérbio</td><td>como ser humano; em forma humana</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropoktonos-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρωποκτόνος anthropoktonos homicida assassino odeia irmão diabo morte Adão 1 João 3.15 João 8.44 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρωποκτόνος</td><td>Substantivo masculino</td><td>homicida; assassino</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropomorphos-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρωπόμορφος anthropomorphos forma humana feras dissidentes Inácio Esmirna BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρωπόμορφος</td><td>Adjetivo</td><td>em forma humana; antropomorfo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropopoietos-bdag\" data-source=\"BDAG\" data-search=\"ἀνθρωποποίητος anthropopoietos feito por ser humano origem humana oferta Barnabé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθρωποποίητος</td><td>Adjetivo</td><td>feito por ser humano; de origem humana</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthropos-bdag\" data-source=\"BDAG\" data-search=\"ἄνθρωπος anthropos ser humano homem pessoa humanidade marido filho escravo indivíduo ser celestial Jesus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄνθρωπος</td><td>Substantivo masculino</td><td>ser humano; homem; pessoa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthupateuo-bdag\" data-source=\"BDAG\" data-search=\"ἀνθυπατεύω anthupateuo exercer proconsulado ser procônsul Gálio Statius Quadratus Atos Policarpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθυπατεύω</td><td>Verbo</td><td>ser procônsul</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anthupatos-bdag\" data-source=\"BDAG\" data-search=\"ἀνθύπατος anthupatos procônsul governo província senatorial Sérgio Paulo Gálio Ásia Chipre Acaia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνθύπατος</td><td>Substantivo masculino</td><td>procônsul</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aniatos-bdag\" data-source=\"BDAG\" data-search=\"ἀνίατος aniatos incurável imperdoável pecado Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνίατος</td><td>Adjetivo</td><td>incurável; imperdoável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aniemi-bdag\" data-source=\"BDAG\" data-search=\"ἀνίημι aniemi soltar desatar abandonar desertar desistir cessar correntes cordas ameaça Atos Hebreus Efésios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνίημι</td><td>Verbo</td><td>soltar; abandonar; cessar</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-aner-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνήρ</h1><div class=\"entry-meta\"><span class=\"greek\">ἀνδρός, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anḗr⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Homero e posteriores; comum em todos os sentidos conhecidos na literatura tratada pelo léxico. <strong>Pessoa do sexo masculino.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Ser humano adulto do sexo masculino, homem, marido.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1a.</span> Em contraste com a mulher, <strong>homem</strong>: Platão, <em>Gorg.</em> 514e; Xenofonte, <em>Hell.</em> 4.5.5 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">15.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">8.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">7ss.</a>; Hm 5.2.2; 6.2.7; 12.2.1 e outros. Daí <span class=\"greek\">ἄνδρα γινώσκειν</span> — compare <span lang=\"he\" dir=\"rtl\">יָדְעָה אִישׁ</span>, Gn 19.8; Jz 11.39 —, de uma mulher: <strong>ter relações sexuais com um homem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.34</a>; compare Justino, <em>D.</em> 78.3, <span class=\"greek\">ἀπὸ συνουσίας ἀνδρός</span>.</p>\n<p class=\"entry-text\">Especialmente <strong>marido</strong>: Homero e outros; Diodoro Sículo 2.8.6; Sir 4.10; Josefo, <em>Ant.</em> 18.149; Ar. 12.2; Fgm. Milne p. 74 linha 3; Justino, <em>A II</em> 2.5ss.; para essa passagem do geral ao específico, compare o inglês coloquial <em>that’s her man</em>, <em>my man</em>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.16</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.16ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.9s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7.2s.</a> (Sb 8010, 21 [papiro do século I d.C.], <span class=\"greek\">μέχρι οὗ ἐὰν συνέρχωμαι ἑτέρῳ ἀνδρί</span>; PLond V, 1731, 16 [século VI d.C.], <span class=\"greek\">κολλᾶσθαι ἑτέρῳ ἀνδρί</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.2ss.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">10ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">14.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.22ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.18s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">5.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.6</a> — sobre as quatro últimas referências, veja <span class=\"greek\">εἷς</span> 2b, os comentários e J. Fischer, <em>Weidenauer Studien</em> 1, 1906, 177–226; comparação com fontes não cristãs em J.-B. Frey, “Signification des termes μονάνδρα et Univira”, RSR 20, 1930, 48–60; G. Delling, <em>Pls’ Stellung z. Frau u. Ehe</em> ’31, 136ss.; B. Easton, <em>Past. Epistles</em>, ’47, 216ss.; W. Schulze, <em>Kerygma und Dogma</em> [Göttingen] 4, ’58, 287–300 —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a>; Hm 4.1.4ss.; 1 Cl 6.3; Pol 4.2; AcPl Ha 4, 5. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2.12</a>; compare Ocellus Luc. c. 49: a esposa deseja <span class=\"greek\">ἄρχειν τοῦ ἀνδρὸς παρὰ τὸν τῆς φύσεως νόμον</span>.</p>\n<p class=\"entry-text\">Até mesmo o <strong>noivo</strong> pode ser assim chamado; compare <span lang=\"he\" dir=\"rtl\">אִישׁ</span>, Dt 22.23: <span class=\"greek\">ὡς νύμφην κεκοσμημένην τῷ ἀνδρὶ αὐτῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21.2</a>.</p>\n<p class=\"entry-text\">Frequente em formas de tratamento, especialmente em assembleias formais: <span class=\"greek\">ἄνδρες</span>, <strong>homens, senhores</strong>; Xenofonte, <em>An.</em> 1.4.14; 1Esd 3.18; 4.14, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 14.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">19.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">27.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.25\" target=\"_blank\" rel=\"noopener noreferrer\">25</a>. <span class=\"greek\">ἄνδρες ἀδελφοί</span>, <strong>(estimados) irmãos</strong>; 4Mc 8.19; compare Xenofonte, <em>An.</em> 1.6.6, <span class=\"greek\">ἄ. φίλοι</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.1\" target=\"_blank\" rel=\"noopener noreferrer\">23.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.17\" target=\"_blank\" rel=\"noopener noreferrer\">28.17</a>; 1 Cl 14.1; 37.1; 43.4; 62.1; AcPl Ha 6, 18; 7, 13; 8.9. <span class=\"greek\">ἀ. ἀδελφοὶ καὶ πατέρες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.2</a>. De soldados, 1Mc 5.17; 16.15: <span class=\"greek\">οἱ ἄ. οἱ συνέχοντες αὐτόν</span>, <strong>os homens que o seguravam</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.63</a>.</p>\n<p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.34</a>, <span class=\"greek\">ἀνήρ</span> parece equivaler a <span class=\"greek\">ἄνθρωπος</span>, mas o termo provavelmente foi escolhido em antecipação ao contraste com <span class=\"greek\">γυνή</span> — seria Dâmaris esposa de um dos homens?</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1b.</span> Em contraste com <strong>menino</strong>; Tb 1.9, embora <span class=\"greek\">ἀνήρ</span> possa ser usado de uma criança, IK VII/2, 14. <span class=\"greek\">ὅτε γέγονα ἀ.</span>, <strong>quando me tornei homem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13.11</a>. <span class=\"greek\">ἀ. τέλειος</span>, <strong>homem plenamente adulto</strong>, Xenofonte, <em>Cyr.</em> 1.2.4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.13</a>; no sentido de maturidade com componente ético, <strong>perfeito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.2</a>; veja 1dα.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1c.</span> Usado com palavra que indica origem nacional ou local, chamando atenção para um indivíduo ou mesmo individualizando o plural; daí, em formas de tratamento — Xenofonte, <em>An.</em> 1.7.3, <span class=\"greek\">ὦ ἄ. Ἕλληνες</span>; Jdt 4.9; 15.13; 1Mc 2.23 —, o singular é omitido na tradução e o plural é vertido por <strong>homens, senhores</strong>, e, em tratamento direto, <strong>estimados habitantes</strong> de determinado lugar. <span class=\"greek\">ἀνὴρ Αἰθίοψ</span>, <strong>um etíope</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.27</a>; compare Xenofonte, <em>An.</em> 1.8.1, <span class=\"greek\">ἀ. Πέρσης</span>; Palaeph. 5; Máximo de Tiro 5.1a, <span class=\"greek\">ἄ. Φρύξ</span>; Taciano 6.1, <span class=\"greek\">Βηρωσσὸς ἀ. Βαβυλώνιος</span>. <span class=\"greek\">ἄ. Ἀθηναῖοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.22</a>; <span class=\"greek\">ἄ. Γαλιλαῖοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1.11</a>; <span class=\"greek\">ἄ. Ἐφέσιοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">19.35</a>; AcPl Ha 1, 24; <span class=\"greek\">ἀ. Ἰουδαῖος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.28</a>; <span class=\"greek\">ἄ. Ἰουδαῖοι</span>, Josefo, <em>Ant.</em> 11.169; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.14</a>; <span class=\"greek\">ἄ. Ἰσραηλῖται</span>, Josefo, <em>Ant.</em> 3.189; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.22</a> — compare 22b, de Jesus, numa hábil manobra retórica —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">5.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">13.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">21.28</a>; <span class=\"greek\">ἄ. Κορίνθιοι</span>, AcPlCor 2.26; <span class=\"greek\">ἄ. Κύπριοι καὶ Κυρηναῖοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.20</a>; <span class=\"greek\">ἀ. Μακεδών</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">16.9</a>. Compare B-D-F §242.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1d.</span> Com foco em características pessoais, positivas ou negativas.</p>\n<p class=\"entry-text\"><strong>α.</strong> Usado com adjetivo: <span class=\"greek\">ἀ. ἀγαθός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.24</a>; <span class=\"greek\">ἀ. ἀγαθὸς καὶ δίκαιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.50</a>; compare <span class=\"greek\">ἀνδραγαθία</span>, Ésquines, <em>C. Ctesiph.</em> 42 e outros; <span class=\"greek\">δεδοκιμασμένοι ἄ.</span>, 1 Cl 44.2; compare Taciano 38.1, <span class=\"greek\">ἄ. δοκιμώτατος</span>; <span class=\"greek\">δίκαιος</span>, Hm 4.1.3; 11.9.13s.; <span class=\"greek\">δίκαιος καὶ ἅγιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.20</a>; <span class=\"greek\">ἀ. δίψυχος, ἀκατάστατος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.8</a>; <span class=\"greek\">ἀ. ἐλλόγιμος</span>, 1 Cl 44.3; <span class=\"greek\">ἀ. ἔνδοξος</span>, Hv 5.1; <span class=\"greek\">ἀ. εὐλαβής</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">22.12</a>; <span class=\"greek\">ἀ. λόγιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">18.24</a>; <span class=\"greek\">ἀ. μεμαρτυρημένος</span>, IPhld 11.1; <span class=\"greek\">ἀ. πιστὸς καὶ ἐλλογιμώτατος</span>, 1 Cl 62.3; <span class=\"greek\">ξένος</span>, AcPl Ox 6, 11 [= Aa I 241, 14]; <span class=\"greek\">ἀ. πονηρός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.5</a> (PsSol 12.1s.); <span class=\"greek\">ἀ. πραΰς</span>, D 15.1; <span class=\"greek\">ἀ. συνετός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.7</a> (Justino, <em>D.</em> 2.6); <span class=\"greek\">ἀ. φρόνιμος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.24</a>; <span class=\"greek\">ἀ. μωρός</span>, v. 26; <span class=\"greek\">ἀ. χρυσοδακτύλιος</span>, <strong>alguém com anéis de ouro nos dedos</strong>, satiricamente <strong>“Sr. Anéis de Ouro”</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.2</a>. <span class=\"greek\">τέλειος ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">3.2</a>; veja 1b.</p>\n<p class=\"entry-text\">Frequentemente em circunlóquios por substantivos, por vezes de modo pleonástico, como o hebraico <span lang=\"he\" dir=\"rtl\">אִישׁ</span>: <span class=\"greek\">οἱ ἄ. τοῦ τόπου</span>, <strong>os habitantes locais</strong>, Gn 26.7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.35</a>. <span class=\"greek\">ἀ. πλήρης λέπρας</span> = <strong>leproso</strong>, em estado grave, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.12</a>; <span class=\"greek\">ἀ. πλήρης πίστεως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">11.24</a>. <span class=\"greek\">ἀ. ἁμαρτωλός</span>, Sir 12.14; 27.30 e outros, <strong>pecador</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">19.7</a>. Em combinações nominais — Ps.-Platão, <em>Axioch.</em> 12 p. 371a, <span class=\"greek\">ἀ. μάγος</span>; Chion, <em>Ep.</em> 14.4, <span class=\"greek\">ἀ. δεσπότης</span>; Máximo de Tiro 19.2a, <span class=\"greek\">ποιμὴν ἀ.</span> —: <span class=\"greek\">ἀ. προφήτης</span>, Jz 6.8, <strong>profeta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.19</a>; <span class=\"greek\">ἀ. πρεσβύτης</span>, veja <span class=\"greek\">πρεσβύτης</span>, MPol 7.2.</p>\n<p class=\"entry-text\"><strong>β.</strong> Com ênfase especial em <strong>coragem ou resistência</strong>, aspecto de forte coloração homérica; Homero e outros; Filóstrato, <em>Vi. Apoll.</em> 1.16 p. 17, 2, em oposição a <span class=\"greek\">ἄνθρωποι</span>, homens de verdade em contraste com meras “pessoas”. Dos apóstolos, 1 Cl 6.1; AcPl Ha 1, 25; 28.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Equivalente a <span class=\"greek\">τίς</span>, <strong>alguém, uma pessoa</strong>: Teógnis 1.199 Diehl²; Xenofonte, <em>Cyr.</em> 2.2.22; Sir 27.7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">19.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4.8</a> (Sl 32.2). No plural, <strong>algumas pessoas</strong>, 1Mc 12.1; 13.34; Justino, <em>D.</em> 108.2 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.11</a>. <span class=\"greek\">ἀνήρ τις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.1</a>. <span class=\"greek\">ἀνὴρ ὅς</span>, como o latim <em>is qui</em>, à maneira do hebraico <span lang=\"he\" dir=\"rtl\">אִישׁ אֲשֶׁר</span>; compare 1Mc 7.7; PsSol 6.1; 10.1 e já Píndaro, <em>P.</em> 9.87, <span class=\"greek\">ἀνήρ τις, ὃς …</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.12</a>. <span class=\"greek\">οἱ κατ’ ἄνδρα</span>, Dió Crisóstomo 15 [32], 6; compare <span class=\"greek\">κατ’ ἄνδρα καὶ οἶκον</span>, PsSol 9.5; <strong>homem por homem, individualmente</strong>, IEph 4.2 — de presbíteros; mas veja J. Kleist, nota no local, <strong>os membros comuns</strong> —; 20.2; ITr 13.2; ISm 5.1; 12.2; IPol 1.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Figura transcendente.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">3a.</span> <strong>Figura de um homem</strong>, de seres celestes que se assemelham a homens; SibOr 3.137, onde os Titãs são assim chamados; Justino, <em>D.</em> 56.5 — veja Gn 18.2 —, 10, <span class=\"greek\">ἐν ἰδέᾳ ἀνδρός</span>; GPt 9.36; 10.39.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3b.</span> De Jesus como <strong>juiz do mundo, designado por Deus</strong>: <span class=\"greek\">ὁ θεὸς … μέλλει κρίνειν τὴν οἰκουμένην ἐν ἀνδρὶ ᾧ ὥρισεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.31</a>; compare Enómao em Eusébio, <em>PE</em> 5.19.3: Minos é o <span class=\"greek\">ἀνήρ, ὃν ἀποδεικνύναι ἐμέλλετε κοινὸν ἀνθρώπων δικαστήν</span>, <strong>o homem que vós [deuses] pretendíeis constituir juiz comum da humanidade</strong>. — Sobre Jesus como figura do <span class=\"greek\">θεῖος ἀνήρ</span>, veja E. Koskenniemi, <em>Apollonius von Tyana in der neutestamentlichen Exegese</em> ’94, com bibliografia. — M. Vock, <em>Bedeutung u. Verwendung von ΑΝΗΡ u. ΑΝΘΡΩΠΟΣ</em> etc., diss. Freiburg 1928; H. Seiler, <em>Glotta</em> 32, ’53, 225–36. — B. 81; 96. DELG. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-anerethen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνῃρέθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anēréthēn⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀναιρέω</span>.</p>\n</section></article><article id=\"entry-anephthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνήφθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anḗphthēn⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνάπτω</span>.</p>\n</section></article><article id=\"entry-anechthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνήχθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anḗchthēn⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνάγω</span>.</p>\n</section></article><article id=\"entry-anthexomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθέξομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthéxomai⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀντέχω</span>.</p>\n</section></article><article id=\"entry-antheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀνθήσω</span>; 1º aoristo <span class=\"greek\">ἤνθησα</span>; perfeito <span class=\"greek\">ἤνθηκα</span>, LXX. Homero e outros; também Justino, <em>A II</em> 11.4, <span class=\"greek\">ἀνθοῦντι … προσώπῳ</span>. <strong>Florescer.</strong> <span class=\"greek\">τὴν γῆν ἀνθοῦσαν ἀμαράντοις ἄνθεσι</span>, <strong>a terra florescendo com flores imperecíveis</strong>, ApcPt 5.15; com o dativo <span class=\"greek\">ἄνθος</span>, como em Homero, <em>Hymn. Ap.</em> 139. — DELG s.v. <span class=\"greek\">ἄνθος</span>.</p>\n</section></article><article id=\"entry-antheros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθηρός</h1><div class=\"entry-meta\"><span class=\"greek\">ά, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthērós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνθέω</span>; Sófocles e outros; Cornuto 30 p. 59, 16; Longo 1.15.3. De cabelo: <strong>esplêndido, brilhante</strong>, ApcPt 3.10. — DELG s.v. <span class=\"greek\">ἄνθος</span>.</p>\n</section></article><article id=\"entry-anthistemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθίστημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthístēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀντιστήσομαι</span>, LXX; 2º aoristo <span class=\"greek\">ἀντέστην</span>; perfeito <span class=\"greek\">ἀνθέστηκα</span>; 1º aoristo passivo <span class=\"greek\">ἀντεστάθην</span>, Hm 12.2.3. De <span class=\"greek\">ἀντί</span> + <span class=\"greek\">ἵστημι</span>; Homero e outros. Literalmente, <strong>“colocar contra”</strong>; as formas que ocorrem na literatura tratada pelo léxico têm sentido médio.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Estar em oposição a, colocar-se contra, opor-se.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1a.</span> A uma pessoa, com dativo <span class=\"greek\">τινί</span>: PGiss 65, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.8</a>. <span class=\"greek\">κατὰ πρόσωπον αὐτῷ ἀντέστην</span>, <strong>opus-me a ele face a face</strong>, Dt 7.24; 9.2; 11.25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.11</a>. <span class=\"greek\">ἀ. Μωϋσεῖ</span>, <strong>opor-se a Moisés</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3.8</a>; <span class=\"greek\">ἀ. τῷ διαβόλῳ</span>, <strong>resistir ao diabo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.7</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 5.9</a>; Hm 12.5.2 e 4. <span class=\"greek\">ἀντιστήτω μοι</span>, <strong>que ele se oponha a mim</strong>, B 6.1; Melito, <em>P.</em> 101, 774; ambos sobre Is 50.8.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1b.</span> De coisas ou forças impessoais, igualmente com dativo: <span class=\"greek\">τινὶ τῇ σοφίᾳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.10</a>. <span class=\"greek\">τ. βουλήματι αὐτοῦ</span>, <strong>à sua vontade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.19</a>; compare Demóstenes 18.49, <span class=\"greek\">τοὺς ἀνθισταμένους τ. ὑμετέροις βουλήμασι</span>. <span class=\"greek\">θεοῦ διαταγῇ</span>, <strong>à ordenação de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.2</a>. <span class=\"greek\">τῷ κράτει τῆς ἰσχύος αὐτοῦ</span>, <strong>ao poder de sua força</strong>, 1 Cl 27.5; compare Wsd 11.21. <span class=\"greek\">τῇ ἀληθείᾳ</span>, <strong>à verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3.8</a>. <span class=\"greek\">τοῖς ἡμετέροις λόγοις</span>, <strong>às nossas palavras</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">4.15</a>; compare Jdt 8.28. <span class=\"greek\">ἐπιθυμίαις</span>, Hm 12.2.3s. <span class=\"greek\">ἀ. τῇ ὀξυχολίᾳ</span>, <strong>resistir ao mau humor</strong>, Hm 5.2.8.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Ser resistente a uma força, resistir</strong>, absolutamente: BGU 747 II, 10; Et 9.2; 3Mc 6.19. <span class=\"greek\">ἵνα δυνηθῆτε ἀντιστῆναι</span>, <strong>para que possais manter-vos firmes</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.13</a>; compare PPetr II, 37, 2a, 14 [século III a.C.], <span class=\"greek\">οὐ δύναμαι ἀνθιστάνειν</span>. <span class=\"greek\">ἀντιστῶμεν</span>, <strong>tomemos posição firme</strong>, B 4.9. <span class=\"greek\">οἱ ἀνθεστηκότες</span>, <strong>os que resistem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.2b</a>, subentendendo-se <span class=\"greek\">τ. διαταγῇ</span>. — DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M.</p>\n</section></article><article id=\"entry-anthomologeomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθομολογέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthomologéomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Imperfeito <span class=\"greek\">ἀνθωμολογούμην</span>. De <span class=\"greek\">ἀντί</span> + <span class=\"greek\">ὁμολογέομαι</span>; com muitos sentidos em Demóstenes e outros; papiros, inclusive PYadin 17, 16; LXX; TestJud 1.3; Josefo, <em>Ant.</em> 8.257; 362. <strong>Louvar, agradecer</strong>; compare o sentido de expressar publicamente agradecimentos em Plutarco, <em>Aemil. Paul.</em> 11.1 e o de reconhecimento em Diodoro Sículo 1.70.6. Com <span class=\"greek\">τῷ θεῷ</span>, <strong>a Deus</strong>: Sl 78.13; Dn 4.37, onde alterna com <span class=\"greek\">ἐξομολογοῦμαι</span>; compare Sir 17.27, 28; 3Mc 6.33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.38</a>. — DELG s.v. <span class=\"greek\">λέγω</span>, <span class=\"greek\">ὁμός</span>. M-M. TW.</p>\n</section></article><article id=\"entry-anthos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνθος</h1><div class=\"entry-meta\"><span class=\"greek\">ους, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánthos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Homero e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Flor, florescência</strong>; especificamente, da flor da videira, 1 Cl 23.4. Figura daquilo que não dura: Quintus Smyrnaeus 14.207, <span class=\"greek\">ἀνδρῶν γὰρ γένος ἐστὶν ὁμοίιον ἄνθεσι ποίης</span>, <strong>a raça dos homens é semelhante às flores da relva</strong>; Zohary, <em>Plants</em> 172s.; Aristaenetus, <em>Ep.</em> 2.1, <span class=\"greek\">πέπαυται τὰ ἄνθη</span>. <span class=\"greek\">ἀ. χόρτου</span>, <strong>flor silvestre</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.10</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">v. 11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.24a-b</a>; ambos em Is 40.6s. <strong>Esplendor colorido</strong>, ApcPt 3.10, na descrição de <span class=\"greek\">κόμη</span>, como em Anacreonte, Fgm. 46 Diehl² [414 Page]. <span class=\"greek\">ἄ. ἀμάραντα</span>, <strong>flores imperecíveis</strong>, ApcPt 5.15.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Fragrância de flores</strong>, ApcPt 5.16. — B. 527. DELG. M-M.</p>\n</section></article><article id=\"entry-anthrakia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρακιά</h1><div class=\"entry-meta\"><span class=\"greek\">ᾶς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthrakiá⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἄνθραξ</span>; Homero e outros; Sir 11.32; 4Mc 9.20. <strong>Fogo de carvão, braseiro.</strong> <span class=\"greek\">ἀ. ποιεῖν</span>, compare PGM 4, 2468, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.18</a>. <span class=\"greek\">ἀ. κειμένη</span>, <strong>um fogo de carvão no chão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.9</a>; a versão latina <em>incensos</em> corresponderia a <span class=\"greek\">ἀ. καιομένη</span> e significaria <strong>uma pilha de carvão em chamas</strong>. Sobre <span class=\"greek\">ἀνθρακιά</span> usado na preparação de peixe e a conexão com Jo 21.9, compare Creophylus de Éfeso [400 a.C.], 417 Fgm. 1 Jac. p. 314, 23s.: <span class=\"greek\">ἁλιέας ἀριστοποιεῖσθαι … τῶν ἰχθύων … σὺν ἀνθρακιᾷ</span>.</p>\n</section></article><article id=\"entry-anthrax-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνθραξ</h1><div class=\"entry-meta\"><span class=\"greek\">ακος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánthrax⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Tucídides, Aristófanes e outros. <strong>Carvão, brasa.</strong> No corpus tratado pelo léxico, somente no provérbio <span class=\"greek\">ἄνθρακας πυρὸς σωρεύειν ἐπὶ τὴν κεφαλήν τινος</span>, <strong>amontoar brasas ardentes sobre a cabeça de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12.20</a>; isto é, <strong>provavelmente fazer a pessoa corar de vergonha e remorso</strong>, Pv 25.22. Compare A. Wright, <em>Interpreter</em> 16, 1920, 159; E. Roberts e F. Jarrat, ibid. 239; A. Fryer, ET 36, 1925, 478; S. Bartstra, NThT 23, ’34, 61–68; S. Morenz, TLZ 78, ’53, 187–92; K. Stendahl, HTR 55, ’62, 343–55, especialmente 346–48, sobre Qumran; W. Klassen, NTS 9, ’63, 337–50; L. Ramarosan, <em>Biblica</em> 51, ’70, 230–34. — DELG. M-M.</p>\n</section></article><article id=\"entry-anthropareskeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρωπαρεσκέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthrōpareskéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἄνθρωπος</span>, <span class=\"greek\">ἀρέσκω</span>; <em>hapax legomenon</em>, mas veja o verbete seguinte. <strong>Ser alguém que procura agradar às pessoas, cortejar/buscar o favor das pessoas</strong>, com conotação de sacrifício de princípio; compare expressões coloquiais inglesas como <em>play up to</em> ou <em>be an apple-polisher</em>. <span class=\"greek\">οὐ θέλω ὑμᾶς ἀνθρωπαρεσκῆσαι</span>, <strong>não quero que busqueis agradar às pessoas</strong>, IRo 2.1; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.10</a>. — DELG s.v. <span class=\"greek\">ἀρέσκω</span>.</p>\n</section></article><article id=\"entry-anthropareskos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρωπάρεσκος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthrōpáreskos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja o verbete precedente; Sl 52.6; PsSol 4.7, 8, 19; compare Nägeli 61; A. Debrunner, <em>Griech. Wortbildungslehre</em>, 1917, 51. Como substantivo, <strong>alguém que procura causar boa impressão nos outros, bajulador, adulador servil</strong>, de escravos que praticam obediência obsequiosa quando seu senhor está olhando, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.22</a>. Em jogo de palavras com <span class=\"greek\">ἑαυτῷ ἀρέσκειν</span>, <strong>agradar aos outros — agradar a si mesmo</strong>, 2 Cl 13.1; W. van Unnik, ZNW Beiheft 26, ’60, 221–34. — M-M. TW.</p>\n</section></article><article id=\"entry-anthropinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρώπινος</h1><div class=\"entry-meta\"><span class=\"greek\">η, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthrṓpinos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἄνθρωπος</span>; pré-socráticos, Heródoto e posteriores. Justino tem o feminino em <span class=\"greek\">-ος</span> em <em>A I</em> 11.1s.; em outros lugares, <span class=\"greek\">-η</span>. <strong>Referente a ser uma pessoa, humano.</strong></p>\n<p class=\"entry-text\"><strong>a.</strong> Em geral. <span class=\"greek\">ἀνθρώπινόν τι πάσχειν</span> = <strong>morrer</strong>: PPetr I, 11, 9ss.; PGen 21, 15; BGU 1149, 34; SIG 1042, 13. <span class=\"greek\">ἀ. ἔργα</span>, <strong>ações humanas</strong>, 1 Cl 59.3; Justino, <em>D.</em> 76.1, singular. <span class=\"greek\">φόβοι ἀ.</span>, <strong>medos humanos</strong>, isto é, próprios da condição humana, 2 Cl 10.3. <span class=\"greek\">συνήθεια ἀ.</span>, IEph 5.1; <span class=\"greek\">φόβῳ</span>, subentendendo-se <span class=\"greek\">ἀ.</span>, AcPl Ha 11, 17. <span class=\"greek\">σάρξ ἀ.</span>, Wsd 12.5; Fílon, <em>Spec. Leg.</em> 4.103; IPhld 7.2. <span class=\"greek\">πειρασμὸς ἀ.</span>, <strong>tentação comum à humanidade</strong>, compare Epicteto 1.9.30; <em>Ench.</em> 26; Nm 5.6, isto é, <strong>suportável</strong>; Pólux 3, 27, 131 também menciona <span class=\"greek\">τὸ ἀνθρώπινον</span> entre os conceitos que contrastam com <span class=\"greek\">ὃ οὐκ ἄν τις ὑπομένειεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10.13</a>. <span class=\"greek\">ἀνθρώπινον λέγειν</span>, <strong>falar em termos humanos</strong>, isto é, como as pessoas falam na vida cotidiana, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.19</a>; compare Plutarco, <em>Mor.</em> 13c; Fílon, <em>Somn.</em> 2.288. <span class=\"greek\">ἀ. ὁ λόγος</span>, <strong>a afirmação é geralmente aceita</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3.1</a> D*; compare 1.15 v.l.; leitura favorecida por Zahn, <em>Einl.</em> I 487; G. Wohlenberg no local; E. Kühl, <em>Erläuterung d. paul. Briefe</em> II 1909, 179; W. Lock, ICC no local e introdução xxxvi, <strong>“fiel às necessidades humanas”</strong>.</p>\n<p class=\"entry-text\"><strong>b.</strong> Em contraste com animal: Diodoro Sículo 3.35.5; Ez 4.15; Dn 7.4, 8. <span class=\"greek\">δεδάμασται τῇ φύσει τῇ ἀ.</span>, <strong>foi domado pela natureza humana ou pela humanidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.7</a>. <span class=\"greek\">ὁ λέων … εἶπεν τῷ Παύλῳ ἀ. γλώσσῃ</span>, <strong>o leão falou a Paulo em língua humana</strong>; compare TestAbr A 3 p. 79, 18s. [Stone p. 6], <span class=\"greek\">ἄ. φωνῇ</span>, de uma árvore; ParJer 7.2, de uma águia.</p>\n<p class=\"entry-text\"><strong>c.</strong> Em contraste com o divino: Máximo de Tiro 38.5e; SIG 526, 29s. [século III a.C.]; 721, 33; 798, 10 [c. 37 d.C.]; Jó 10.5; 4Mc 1.16s.; 4.13; Josefo, <em>Bell.</em> 6.429. <span class=\"greek\">ἀ. μυστήρια</span>, <strong>segredos meramente humanos</strong>, Dg 7.1. <span class=\"greek\">ὑπὸ χειρῶν ἀ. θεραπεύεται</span>, <strong>é servido por mãos humanas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.25</a>; compare <span class=\"greek\">χ. ἀ.</span>, Josefo, <em>Bell.</em> 5.387; 400; Justino, <em>A I</em> 20.5. <span class=\"greek\">ἀ. σοφία</span>, <strong>sabedoria humana</strong>, Fílon, <em>Rer. Div. Her.</em> 126; Josefo, <em>Ant.</em> 3.223, <span class=\"greek\">σύνεσις ἀ.</span>; Justino, <em>D.</em> 80.3, <span class=\"greek\">διδάγματα ἀ.</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 2.4</a> v.l., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>. <span class=\"greek\">ἀ. ἡμέρα</span>, <strong>tribunal humano</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4.3</a>. <span class=\"greek\">πρόσκλισις ἀ.</span>, <strong>parcialidade humana</strong>, 1 Cl 50.2. <span class=\"greek\">δόγμα ἀ.</span>, <strong>opinião humana</strong>, Dg 5.3. <span class=\"greek\">ἀ. κτίσις</span>, <strong>instituição humana das autoridades</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.13</a>. — DELG s.v. <span class=\"greek\">ἄνθρωπος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-anthropinos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρωπίνως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthrōpínōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνθρώπινος</span>; Tucídides; Andócides 1.57; 2.6 e outros; PSI XII, 1248, 17 [século III d.C.]; TestSol 10.3 C; Josefo, <em>Ant.</em> 19.4; Taciano 4.1. <strong>Como ser humano.</strong> <span class=\"greek\">θεοῦ ἀ. φανερουμένου</span>, <strong>quando Deus apareceu em forma humana</strong>, IEph 19.3. — M-M.</p>\n</section></article><article id=\"entry-anthropoktonos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρωποκτόνος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthrōpoktónos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">κτείνω</span>, <strong>“matar”</strong>; raro: Eurípides, <em>Cycl.</em> 127; <em>Iph. T.</em> 389; Taciano 8.3; Melito, todos como adjetivo; Ps.-Plutarco, <em>De Fluv.</em> 1165a; Nicetas Eugen. 8, 225H. <strong>Homicida, assassino.</strong> De quem odeia seu irmão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.15</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.21s.</a>. Do diabo: <span class=\"greek\">ἀ. ἦν ἀπ’ ἀρχῆς</span>, <strong>era homicida desde o princípio</strong>, não com referência ao assassinato de Abel, mas para designar o diabo como aquele que trouxe a morte ao mundo ao enganar Adão, Wsd 2.24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.44</a>. — DELG s.v. <span class=\"greek\">κτείνω</span>. M-M.</p>\n</section></article><article id=\"entry-anthropomorphos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρωπόμορφος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthrōpómorphos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">μορφή</span>; Epicuro, Fgm. 353 Us., <span class=\"greek\">θεός</span>; segundo Diodoro Sículo 40.3.4, Moisés recusou-se a crer em <span class=\"greek\">θ. ἀνθρωπόμορφος</span>; Diodoro Sículo 3.62.2, de Dioniso; 22.9.4, <span class=\"greek\">θεοὶ ἀ.</span>; Estrabão 16.2.35, <span class=\"greek\">τὸ θεῖον</span>; Cornuto 27 p. 49, 7; Diógenes Laércio; Plutarco, <em>Mor.</em> 149c-d; 167d; TestSol 18.1; Fílon, <em>Op. M.</em> 69. <strong>Em forma humana, antropomorfo.</strong> <span class=\"greek\">θηρία ἀ.</span>, <strong>feras em forma humana</strong>, compare Fílon, <em>Abr.</em> 33; de dissidentes, ISm 4.1. — DELG s.v. <span class=\"greek\">μορφή</span>.</p>\n</section></article><article id=\"entry-anthropopoietos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθρωποποίητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthrōpopoíētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Literalmente, <strong>“algo feito por um ser humano”</strong>. <span class=\"greek\">προσφορὰ ἀ.</span>, <strong>uma oferta de origem humana</strong>, B 2.6. — DELG s.v. <span class=\"greek\">ποιέω</span>.</p>\n</section></article><article id=\"entry-anthropos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄνθρωπος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánthrōpos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Homero e posteriores; palavra tomada de empréstimo no rabínico. O feminino <span class=\"greek\">ἡ ἄνθρωπος</span> (Heródoto 1.60.5) não aparece na literatura tratada pelo léxico. <strong>Ser humano, homem, pessoa.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Pessoa de qualquer sexo, com foco na participação na raça humana, ser humano.</strong></p>\n<p class=\"entry-text\"><strong>a.</strong> <span class=\"greek\">ἐγεννήθη ἄ.</span>, Jo 16.21; <span class=\"greek\">εἰς χεῖρας ἀ.</span>, Mc 9.31; <span class=\"greek\">ψυχὴ ἀνθρώπου</span>, Rm 2.9; <span class=\"greek\">συνείδησις ἀ.</span>, 2Co 4.2; <span class=\"greek\">μέτρον ἀ.</span>, Ap 21.17.</p>\n<p class=\"entry-text\"><strong>b.</strong> Em contraste com animais, plantas etc.: Mt 4.19; 12.12; Mc 1.17; Lc 5.10; 1Co 15.39; 2Pe 2.16; Ap 9.4, 7; 13.18. Em contraste com anjos: compare Aristaenetus 1.24, final, <span class=\"greek\">σάτυροι οὐκ ἄνθρωποι</span>; 1Co 4.9; 13.1. Em contraste com Deus: Ésquilo, <em>Ag.</em> 663 <span class=\"greek\">θεός τις οὐκ ἄνθ.</span>; Ésquines 3.137; Aélio Aristides 30 p. 578 D.; Herm. Wr. 14.8; PsSol 2.28; Hb 13.6 (Sl 117.6); Mt 10.32s.; 19.6; Mc 10.9; Jo 10.33, onde <span class=\"greek\">ἄνθ. ὤν</span> = <strong>“sendo um ser humano mortal”</strong>, fórmula recorrente; compare Xenofonte, <em>An.</em> 7.6.11; Menandro, <em>Epitr.</em> 592 Kö.; Fgm. 46; 395, 2 Kö.; Comp. I 282; Alexis Com., Fgm. 150; Políbio 3.31.3; Chariton 4.4.8 [WBlake ’38]; Heliodoro 6.9.3; já Eurípides, <em>Hipp.</em> 472ss. <span class=\"greek\">ἄνθρωπος οὖσα … κρείσσω δαιμόνων εἶναι θέλειν</span>; At 10.26; 12.22; 14.11, 15; 1Ts 2.13; Fp 2.7. <span class=\"greek\">ἐντάλματα ἀνθρώπων</span>, <strong>preceitos humanos</strong>, Mt 15.9; Mc 7.7 (Is 29.13); com <span class=\"greek\">οὐρανός</span> (= Deus), Mt 21.25; Mc 11.30. <span class=\"greek\">ἀδύνατα παρὰ ἀνθρώποις</span>, Lc 18.27; compare Mt 19.26. <span class=\"greek\">δοῦλοι ἀνθρώπων</span>, <strong>escravos de pessoas</strong>, 1Co 7.23. <span class=\"greek\">πείθειν</span> e <span class=\"greek\">ἀρέσκειν ἀ.</span>, Gl 1.10. <span class=\"greek\">μεσίτης θεοῦ καὶ ἀ.</span>, 1Tm 2.5. <span class=\"greek\">θεὸς πάντας ἀνθρώπους θέλει σωθῆναι</span>, 1Tm 2.4; compare Epicteto 3.24.2.</p>\n<p class=\"entry-text\"><strong>c.</strong> No plural, com sentido geral, <span class=\"greek\">οἱ ἄ.</span>, <strong>as pessoas</strong>, também <strong>os associados de alguém</strong>: Josefo, <em>Ant.</em> 9.28; Mt 5.13, 16; 6.1s., 5, 14, 18; 7.12; 8.27; 23.5; Mc 8.27 e frequentemente. <span class=\"greek\">οἱ τότε ἄ.</span>, <strong>as pessoas daquele tempo</strong>, Pol 3.2. <span class=\"greek\">οἱ υἱοὶ τῶν ἀνθρώπων</span>, <strong>os descendentes dos seres humanos</strong> ou simplesmente <strong>seres humanos, pessoas</strong>, Gn 11.5; 1Esd 4.37; Sl 10.4; En 10.7; PsSol 9.4; Mc 3.28; Ef 3.5. Semelhantemente, <span class=\"greek\">ὁ υἱὸς τοῦ ἀ.</span> como autodesignação de Jesus; veja adiante, também 2a e <span class=\"greek\">υἱός</span> 2dγ.</p>\n<p class=\"entry-text\"><strong>d.</strong> Jesus Cristo é chamado <span class=\"greek\">ἄ.</span> como aquele que se identifica com a humanidade; compare <span class=\"greek\">ὁ Σωτὴρ ἄ. γενόμενος</span>, Did., <em>Gen.</em> 41.28; 1Tm 2.5; Hb 2.6a (Sl 8.5a; compare Justino, <em>A II</em> 6.4). Ele é contrastado com Adão em Rm 5.15; 1Co 15.21; o <span class=\"greek\">πρῶτος ἄ.</span>, 1Co 15.45, 47 (compare Fílon, <em>Abr.</em> 56; DDD 112), em contraste com o <span class=\"greek\">δεύτερος ἄ.</span>, v. 47. Sobre a natureza e origem do conceito, compare Ltzm. e JWeiss em 1Co 15.45ss.; WBousset, <em>Kyrios Christos</em>², 1921, 120ss.; <em>Jesus der Herr</em>, 1916, 67ss.; Rtzst., <em>Mysterienrel.</em>³ 343ss.; <em>Erlösungsmyst.</em> 107ss.; ARawlinson, <em>The NT Doctrine of the Christ</em>, 1926, 124ss.; BStegmann, <em>Christ, the “Man from Heaven”</em>, 1927; CKraeling, <em>Anthropos and Son of Man</em>, 1927. Veja também <span class=\"greek\">Ἀδάμ</span> e <span class=\"greek\">οὐρανός</span> 2b; sobre <span class=\"greek\">ὁ υἱὸς τοῦ ἀ.</span>, veja também <span class=\"greek\">υἱός</span> 2dγ.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Membro da raça humana, com foco nas limitações e fraquezas, ser humano.</strong></p>\n<p class=\"entry-text\"><strong>a.</strong> Quanto ao aspecto físico, Tg 5.17; sujeito à morte, Hb 9.27; Ap 8.11; Rm 5.12; afundado no pecado — compare, sob perspectiva diferente, Menandro, Fgm. 432 Kö. [499 K.] <span class=\"greek\">ἄνθρωπος ὢν ἥμαρτον</span>; Herodas 5.27 <span class=\"greek\">ἄνθρωπός εἰμι, ἥμαρτον</span>; escólio a Apolônio de Rodes 4.1015–17a; Orígenes, <em>C. Cels.</em> 3.62.17 —, Rm 5.18s.; daí julgado inferior, Gl 1.1, 11s.; Cl 2.8, 22 (Is 29.13), ou mesmo alguém de quem se deve cuidadosamente evitar: <span class=\"greek\">προσέχειν ἀπὸ τ. ἀ.</span>, <strong>guardar-se de homens maus</strong>, Mt 10.17; compare Lc 6.22, 26.</p>\n<p class=\"entry-text\"><strong>b.</strong> Quanto ao status, <span class=\"greek\">κατὰ ἄνθρωπον</span>, <strong>de modo humano, do ponto de vista humano</strong>, enfatizando a inferioridade humana em comparação com Deus: Ésquilo, <em>Sept.</em> 425; Platão, <em>Phileb.</em> 370f; Diodoro Sículo 16.11.2; Ateneu 10.444b; Plutarco, <em>Mor.</em> 1042a; Witkowski 8, 5 [252 a.C.]; <span class=\"greek\">λαλεῖν</span>, 1Co 9.8; <span class=\"greek\">λέγειν</span>, Rm 3.5; Gl 3.15; <span class=\"greek\">περιπατεῖν</span>, 1Co 3.3. <span class=\"greek\">κ. ἄ. ἐθηριομάχησα</span>, talvez <strong>como um homem comum</strong>, em oposição ao cristão seguro da ressurreição, 1Co 15.32. Do evangelho, <span class=\"greek\">οὐκ ἔστιν κ. ἄ.</span>, Gl 1.11. Plural <span class=\"greek\">κ. ἀνθρώπους</span>, em oposição a <span class=\"greek\">κ. θεόν</span>, 1Pe 4.6.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Pessoa do sexo masculino, homem.</strong> <strong>a.</strong> <strong>Homem adulto</strong>: Platão, <em>Prot.</em> 6, 314e; <em>Phd.</em> 66, 117e; Gn 24.26ss.; PsSol 17.17; TestAbr A 3 p. 79, 25 [Stone p. 6]; ParJer 5.20; Mt 11.8; Lc 7.25. <span class=\"greek\">σκληρὸς εἶ ἄ.</span>, Mt 25.24; compare Lc 19.21s. Em contraste com mulher: Aquiles Tácio 5.22.2; PGM 36, 225s.; 1Esd 9.40; Tb 6.8; Mt 19.5; provavelmente Lc 13.19 (compare v. 21); Ef 5.31 (ambos Gn 2.24); 1Co 7.1; Ox 840, 39. <strong>b.</strong> <strong>Pessoa casada, marido</strong>, Mt 19.10. <strong>c.</strong> <strong>Descendente imediato, filho</strong>, em oposição ao pai, Sir 3.11; Mt 10.35. <strong>d.</strong> <strong>Pessoa possuída e, portanto, sob o controle de outra, escravo</strong>: Xenofonte, <em>Mem.</em> 2.1.15; <em>Vect.</em> 4.14; Herodas 5.78; BGU 830, 4; POxy 1067, 30; 1159, 16; Lc 12.36. <span class=\"greek\">οἱ τοῦ πυρὸς ἄ.</span>, <strong>os encarregados do fogo</strong>, MPol 15.1; <span class=\"greek\">ἄ. τοῦ μεγάλου βασιλέως</span>, AcPl Ha 9, 1 (Aa I 111, 10). Talvez Jo 6.7.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Praticamente equivalente ao pronome indefinido, com o sentido básico de <span class=\"greek\">ἄνθρωπος</span> muito enfraquecido: alguém, um, uma pessoa.</strong></p>\n<p class=\"entry-text\"><strong>a.</strong> Sem artigo. <strong>α.</strong> Com <span class=\"greek\">τις</span>: <span class=\"greek\">ἐὰν γένηταί τινι ἀνθρώπῳ</span>, Mt 18.12; <span class=\"greek\">ἄνθρωπός τις κατέβαινεν</span>, <strong>um homem descia</strong>, Lc 10.30; <span class=\"greek\">ἀνθρώπου τινὸς πλουσίου</span>, 12.16; <span class=\"greek\">ἄ. τις ἦν ὑδρωπικός</span>, 14.2, compare v. 16; 15.11; 16.1, 19; 19.12; <span class=\"greek\">ἦν τις ἄ. ἐκεῖ</span>, Jo 5.5; <span class=\"greek\">τινῶν ἀ. αἱ ἁμαρτίαι</span>, 1Tm 5.24.</p>\n<p class=\"entry-text\"><strong>β.</strong> Sem <span class=\"greek\">τις</span>, às vezes quase equivalente a ele: Pausânias 5.7.3 <span class=\"greek\">ἐξ ἀνθρώπου</span> = <strong>de alguém</strong>. <span class=\"greek\">εἷς ἄ.</span> = <span class=\"greek\">εἷς τις</span>, <strong>um indivíduo</strong>, Jo 11.50; compare 18.14. <span class=\"greek\">εἶδεν ἄνθρωπον καθήμενον</span>, <strong>viu alguém sentado</strong>, Mt 9.9. <span class=\"greek\">ἰδοὺ ἄ. χεῖρα ἔχων ξηράν</span>, <strong>havia alguém com a mão ressequida</strong>, Mt 12.10. Compare ainda Mc 1.23; 3.1; 4.26; 5.2; 7.11; 10.7; Lc 2.25; 4.33; 5.18; 6.48s.; 13.19; Jo 3.4, 27. Com negativas, <span class=\"greek\">ἄ. οὐκ ἔχω</span>, <strong>não tenho ninguém</strong>, Jo 5.7; <span class=\"greek\">οὐδέποτε ἐλάλησεν οὕτως ἄ.</span>, <strong>ninguém jamais falou assim</strong>, 7.46.</p>\n<p class=\"entry-text\"><strong>γ.</strong> Em sentido indefinido e ao mesmo tempo geral, frequentemente = <strong>alguém, uma pessoa</strong>: <span class=\"greek\">οὕτως ἡμᾶς λογιζέσθω ἄ.</span>, literalmente <strong>assim uma pessoa deve considerar-nos</strong>, 1Co 4.1; compare Mt 16.26; Rm 3.28; 1Co 7.26; 11.28; Gl 2.16; 6.7; Tg 2.24.</p>\n<p class=\"entry-text\"><strong>δ.</strong> Com oração relativa: <span class=\"greek\">δεῦτε ἴδετε ἄ. ὃς εἶπέν μοι</span>, <strong>vinde ver alguém que me disse</strong> — em contraste com <span class=\"greek\">ἀνήρ</span> nos vv. 16–18 —, Jo 4.29; <span class=\"greek\">ἄ. ὃς τὴν ἀλήθειαν ὑμῖν λελάληκα</span>, 8.40. Para At 19.16, veja 6 abaixo.</p>\n<p class=\"entry-text\"><strong>ε.</strong> Pleonástico com substantivo: <span class=\"greek\">ἄ. φάγος</span>, <strong>glutão</strong>, Mt 11.19; Lc 7.34; <span class=\"greek\">ἄ. ἔμπορος</span>, <strong>mercador</strong>, Mt 13.45; <span class=\"greek\">ἄ. οἰκοδεσπότης</span>, v. 52; 21.33; <span class=\"greek\">ἄ. βασιλεύς</span>, 18.23; 22.2; <span class=\"greek\">ἄ. θηριομάχος</span>, AcPl Ha 5, 30. Semelhantemente com nomes de origem local ou nacional: <span class=\"greek\">ἄ. Κυρηναῖος</span>, <strong>um cireneu</strong>, Mt 27.32; <span class=\"greek\">ἄ. Ἰουδαῖος</span>, At 21.39; <span class=\"greek\">ἄ. Ῥωμαῖος</span>, 16.37; 22.25. Com adjetivo substantivado: <span class=\"greek\">ἄ. τυφλός</span>, <strong>cego</strong>, Jo 9.1; <span class=\"greek\">ἄ. ἁμαρτωλός</span>, v. 16; <span class=\"greek\">ἄ. αἱρετικός</span>, Tt 3.10. Com particípio, <span class=\"greek\">ἄ. σπείρων</span>, <strong>semeador</strong>, Mt 13.24.</p>\n<p class=\"entry-text\"><strong>ζ.</strong> Também são pleonásticas combinações como <span class=\"greek\">τίς ἄ.</span>, <strong>quem?</strong>, Mt 7.9; Lc 15.4; <span class=\"greek\">πᾶς ἄ.</span>, <strong>todo mundo</strong>, Jo 2.10; Tg 1.19; <span class=\"greek\">πάντες ἄ.</span>, <strong>todas as pessoas</strong>, At 22.15, <strong>todos</strong>, 1Co 7.7; <span class=\"greek\">εἷς ἄ.</span>, Jo 11.50; <span class=\"greek\">δύο ἄ.</span>, Lc 18.10; e o genitivo partitivo <span class=\"greek\">ἀνθρώπων</span> com <span class=\"greek\">οὐδείς</span>, Mc 11.2; Lc 19.30, <span class=\"greek\">μηδείς</span>, At 4.17, <span class=\"greek\">τίς</span>, 19.35; 1Co 2.11. — MBlack, <em>An Aramaic Approach</em>³, 1967, 106s.</p>\n<p class=\"entry-text\"><strong>b.</strong> Com artigo genérico: <span class=\"greek\">ὁ ἀγαθὸς ἄ.</span>, <strong>a pessoa boa</strong>, em oposição a <span class=\"greek\">ὁ πονηρὸς ἄ.</span>, <strong>a pessoa má</strong>, Mt 12.35. <span class=\"greek\">οὐκ ἐπ’ ἄρτῳ ζήσεται ὁ ἄ.</span>, <strong>ninguém viverá só de pão</strong>, Mt 4.4 (Dt 8.3). <span class=\"greek\">κοινοῖ τὸν ἄ.</span>, <strong>contamina a pessoa</strong>, Mt 15.11, 18; compare Mc 7.15, 20; <span class=\"greek\">τὸ σάββατον διὰ τὸν ἄ. ἐγένετο</span>, Mc 2.27; <span class=\"greek\">τί ἦν ἐν τῷ ἀ.</span>, Jo 2.25; <span class=\"greek\">κρίνειν τὸν ἄ.</span>, Jo 7.51; <span class=\"greek\">ὁ νόμος κυριεύει τοῦ ἀ.</span>, Rm 7.1; <span class=\"greek\">ὁ ποιήσας ἄ.</span>, <strong>todo aquele que o pratica</strong>, Rm 10.5 (Lv 18.5; 2Esd 19.29); <span class=\"greek\">κακὸν τῷ ἀ. τῷ διὰ προσκόμματος ἐσθίοντι</span>, <strong>é mau para quem come com escrúpulos</strong>, Rm 14.20.</p>\n<p class=\"entry-text\"><strong>c.</strong> Com genitivo qualificativo: <span class=\"greek\">ἄνθρωποι εὐδοκίας</span>, Lc 2.14; <span class=\"greek\">ὁ ἄ. τῆς ἀνομίας</span> (v.l. <span class=\"greek\">ἁμαρτίας</span>), 2Ts 2.3; <span class=\"greek\">ἄ. (τοῦ) θεοῦ</span>, <strong>homem de Deus</strong>, 1Tm 6.11; 2Tm 3.17; 2Pe 1.21 v.l.; compare 3Km 12.22; 13.1; 17.24; 4Km 1.9ss.; 2Cr 8.14; TestJob 53.4; EpArist 140; Fílon, <em>Gig.</em> 61, <em>Deus Imm.</em> 138s.; Sextus 2; 3; Herm. Wr. 1.32; 13.20; PGM 4, 1177.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Ser humano em conflito em nível transcendente.</strong> <strong>a.</strong> Os dois lados da natureza humana como <span class=\"greek\">ὁ ἔξω ἄ.</span>, <strong>o ser exterior</strong>, isto é, seres humanos em seus aspectos materiais, transitórios e pecaminosos, 2Co 4.16; e <span class=\"greek\">ὁ ἔσω ἄ.</span>, <strong>o ser interior</strong>, isto é, humanos em sua significação transcendente, voltando-se para Deus, Rm 7.22; 2Co 4.16; Ef 3.16; compare Platão, <em>Rep.</em> 9, 589a; Plotino, <em>Enn.</em> 5.1.10; Fílon, <em>Plant.</em> 42; <em>Congr. Erud. Grat.</em> 97; <em>Det. Pot. Insid.</em> 23; Zósimo em Rtzst., <em>Poim.</em> 104; Rtzst., <em>Mysterienrel.</em>³ 354s.; WGutbrod, <em>D. paulin. Anthropologie</em>, 1934; KSchäfer, FTillmann Festschr. 1934, 25–35; RJewett, <em>Paul’s Anthropological Terms</em>, 1971, 391–401. Semelhante é <span class=\"greek\">ὁ κρυπτὸς τῆς καρδίας ἄ.</span>, <strong>a pessoa oculta do coração</strong> = <span class=\"greek\">ὁ ἔσω ἄ.</span>, 1Pe 3.4.</p>\n<p class=\"entry-text\"><strong>b.</strong> De outra perspectiva, com contraste de <span class=\"greek\">παλαιὸς</span> e <span class=\"greek\">καινὸς</span> (<span class=\"greek\">νέος</span>) <span class=\"greek\">ἄ.</span>, Rm 6.6; Ef 4.22, 24; Cl 3.9; compare Dg 2.1; Jesus como <span class=\"greek\">καινὸς ἄ.</span> em IEph 20.1 é o novo ser, que é realmente Deus; ou contraste de <span class=\"greek\">ὁ ψυχικὸς ἄ.</span> e <span class=\"greek\">ὁ πνευματικὸς ἄ.</span>, 1Co 2.14s.; veja <span class=\"greek\">πνευματικός</span> 2aγ. <span class=\"greek\">τὸν τέλειον ἄ.</span>, GMary 463, 27.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">6.</span> <strong>Pessoa que acaba de ser mencionada numa narrativa</strong>, com artigo: Diodoro Sículo 37.18; Justino, <em>A II</em> 2.12; Mt 12.13; Mc 3.5; 5.8; Jo 4.50; At 19.16 e outros.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">7.</span> <strong>Pessoa percebida como desprezível, certa pessoa</strong>, com conotação de desprezo: Diógenes Epicureu, em Eusébio, <em>PE</em> 6.8.30, chama depreciativamente Crisipo de <span class=\"greek\">ὁ ἄ.</span>; Artemidoro 5.67, <span class=\"greek\">ἡ ἄνθρωπος</span> de uma prostituta; UPZ 72, 6 [152 a.C.]; BGU 1208 I, 25; Plutarco, <em>Mor.</em> 870c. <span class=\"greek\">οὐκ οἶδα τὸν ἄ.</span>, <strong>não conheço esse sujeito</strong>, de Jesus, Mt 26.72, 74; Mc 14.71. <span class=\"greek\">προσηνέγκατέ μοι τὸν ἄ. τοῦτον</span>, Lc 23.14; <span class=\"greek\">ὁ ἄ. οὕτος</span>, AcPl Ox 6, 18; <span class=\"greek\">εἰ ὁ ἄ. Γαλιλαῖός ἐστιν</span>, Lc 23.6; <span class=\"greek\">τίς ἐστιν ὁ ἄ.</span>, Jo 5.12; <span class=\"greek\">ἰδοὺ ὁ ἄ.</span>, <strong>eis o homem!</strong>, Jo 19.5, numa tentativa de suscitar piedade; <span class=\"greek\">μὴ οἰέσθω ὁ ἄ. ἐκεῖνος</span>, <strong>tal pessoa não deve esperar</strong>, Tg 1.7.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">8.</span> <strong>Em tratamento direto</strong>, variando de tom familiar a mais formal: <span class=\"greek\">ἄνθρωπε</span>, <strong>amigo</strong>, Xenofonte, <em>Cyr.</em> 2.2.7; Plutarco, <em>Mor.</em> 553e; Lc 5.20; <strong>senhor</strong>, <span class=\"greek\">Ἄνθρωπε, ποῦ πορεύῃ;</span>, GJs 19.1, onde a mulher é estranha a José. Com conotação de censura, <strong>homem!</strong>, Lc 12.14; 22.58, 60; Hm 10.1.2. Também em apóstrofe retórica numa carta, Rm 2.1, 3; 9.20; Tg 2.20; compare Platão, <em>Apol.</em> 16 p. 28b; índice de Epicteto em Schenkl; Mq 6.8; Sl 54.14; JWackernagel, <em>Über einige antike Anredeformen</em>, 1912.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">9.</span> <strong>Ser celestial que parecia uma pessoa, figura humana</strong>, GPt 11.44; compare Justino, <em>D.</em> 58.10, <span class=\"greek\">ἐν ἰδέᾳ ἀνθρώπου</span>, sobre Gn 32.25; Taciano 21.1, <span class=\"greek\">θεὸν ἐν ἀνθρώπου μορφῇ γεγονέναι</span>. — JNielen, <em>D. Mensch in der Verkünd. der Ev.</em>, FTillmann Festschr. 1934, 14–24; Gutbrod op. cit. 2cα; WKümmel, <em>Man in the NT</em>, trad. JVincent, 1963; veja também Vock e Seiler ao final de <span class=\"greek\">ἀνήρ</span>. — B. 80. EDNT (lit.). DELG. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-anthupateuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθυπατεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anthupateúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνθύπατος</span>; Plutarco, <em>Cic.</em> 887 [52.7]; Herodiano 7.5.2; OGI 517, 10. <strong>Ser procônsul.</strong> At 18.12 v.l.; <span class=\"greek\">ἀνθυπατεύοντος Στατίου Κοδράτου</span>, <strong>quando Statius Quadratus era procônsul</strong>, MPol 21. — DELG s.v. <span class=\"greek\">ὕπατος</span>.</p>\n</section></article><article id=\"entry-anthupatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνθύπατος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anthúpatos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀντί</span> + <span class=\"greek\">ὕπατος</span>, originalmente <strong>“o mais alto”</strong> e depois <strong>“cônsul”</strong>; Políbio e outros; frequente na literatura; Josefo, <em>Ant.</em> 14.236; 244 e outros; Melito; inscrições — veja, por exemplo, PHermann, <em>Inschriften von Sardeis</em>: Chiron 23, 1993, 233–48, sobre um homenageado de 211 d.C., pp. 238s. —; papiros, inclusive Ox 850 verso 15: AcJ. <strong>Chefe do governo numa província senatorial, procônsul.</strong> São mencionados o procônsul de Chipre, Sérgio Paulo, At 13.7, compare vv. 8 e 12; o da Acaia, Gálio, At 18.12, compare 19.38; e o da Ásia, MPol 3.1; 4; 9.2, 3; 10.2; 11.1; 12.1. — DELG s.v. <span class=\"greek\">ὕπατος</span>. M-M.</p>\n</section></article><article id=\"entry-aniatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνίατος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aníatos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀ-</span> privativo + <span class=\"greek\">ἰάομαι</span>, <strong>“curar”</strong>; Hipócrates, Platão e outros; IG III add. 171a, 23 p. 474, de uma ferida “incurável” curada por Asclépio; papiros, LXX; TestSol 18.20, 23; Josefo, <em>Ant.</em> 19.325 [adv.]; Justino, <em>D.</em> 132.2. <strong>Incurável</strong>, na literatura tratada somente em sentido figurado; Ésquines 3.156 <span class=\"greek\">κακά</span>; TestReub 6.3. <span class=\"greek\">ἁμαρτία μεγάλη καὶ ἀ.</span>, <strong>um pecado grande e imperdoável</strong>, Hm 5.2.4; compare Fílon, <em>Somn.</em> 1.87 <span class=\"greek\">τὰ ἀνίατα τ. ἁμαρτημάτων</span>; Platão, <em>Gorg.</em> 525c. — DELG s.v. <span class=\"greek\">ἰάομαι</span>.</p>\n</section></article><article id=\"entry-aniemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνίημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aníēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀνήσω</span>, LXX; 1º aoristo <span class=\"greek\">ἀνῆκα</span>; 2º aoristo subjuntivo <span class=\"greek\">ἀνῶ</span>, particípio <span class=\"greek\">ἀνείς</span>. Passivo: 1º aoristo <span class=\"greek\">ἀνέθην</span>, sem aumento, B-D-F §67, 2; particípio perfeito <span class=\"greek\">ἀνειμένος</span>, LXX. Veja <span class=\"greek\">ἵημι</span>; Homero e posteriores; inscrições, papiros, LXX, Josefo; Nägeli 16; 20.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Soltar, desatar</strong>, de correntes: <em>Od.</em> 8.359; Calímaco, Fgm. 260, 29 [<em>Hecale</em>] Pf., <span class=\"greek\">δεσμά</span>; Plutarco, <em>Alex.</em> 705 [73.9] <span class=\"greek\">τοὺς δεσμούς</span>; Justino, <em>D.</em> 9.2, de uma pessoa; <span class=\"greek\">πάντων τὰ δεσμὰ ἀνέθη</span>, <strong>soltou as cadeias de todos</strong>, At 16.26; veja <span class=\"greek\">ἀναλύω</span>. De cordas, <span class=\"greek\">ἀ. τὰς ζευκτηρίας</span>, At 27.40.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Abandonar, desertar alguém.</strong> <span class=\"greek\">οὐ μή σε ἀνῶ</span>, literalmente como em Fílon, <em>Conf. Lingu.</em> 166; veja PKatz, <em>Biblica</em> 33, 1952, 523–25; <strong>jamais te abandonarei</strong>, Hb 13.5.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Desistir, cessar de algo.</strong> Tucídides 3.10.4; Plutarco, <em>Alex. M.</em> 704 [70.6] <span class=\"greek\">τὴν ὀργήν</span>; Josefo, <em>Ant.</em> 14.286. <span class=\"greek\">ἀ. τὴν ἀπειλήν</span>, <strong>cessar as ameaças</strong>, Ef 6.9. — DELG s.v. <span class=\"greek\">ἵημι</span>. M-M. TW.</p>\n</section></article>"};
